update platform_app_execution
release_no = #{releaseNo,jdbcType=INTEGER}, `status` = #{status,jdbcType=VARCHAR}, stage = #{stage,jdbcType=VARCHAR}, message = #{message,jdbcType=VARCHAR}, lease_until = #{leaseUntil,jdbcType=TIMESTAMP}, finished_at = #{finishedAt,jdbcType=TIMESTAMP},
where id = #{id,jdbcType=BIGINT}

update platform_app_execution
   set lease_until = #{leaseUntil,jdbcType=TIMESTAMP},
       owner_id   = #{ownerId,jdbcType=VARCHAR}
 where id = #{id,jdbcType=BIGINT}
   and `status` in ('PENDING', 'RUNNING')
   and (owner_id = #{ownerId,jdbcType=VARCHAR}
        or lease_until is null
        or lease_until < #{now,jdbcType=TIMESTAMP})

update platform_app_execution
   set lease_until = null
 where owner_id = #{ownerId,jdbcType=VARCHAR}
   and `status` in ('PENDING', 'RUNNING')

   and id not in
  #{x,jdbcType=BIGINT}
